<?php
require_once __DIR__.'/../includes/auth.php'; require_role('superadmin','hr','finance'); require_once __DIR__.'/../includes/layout.php'; require_once __DIR__.'/../includes/lcc_payroll.php';
$canEditAttendance=admin_role()!=='finance';
function clock_minutes(?string $time): ?int { if(!$time||!preg_match('/^([01][0-9]|2[0-3]):([0-5][0-9])/', $time,$m))return null; return (int)$m[1]*60+(int)$m[2]; }
$error='';$message='';
if($_SERVER['REQUEST_METHOD']==='POST'){
    require_role('superadmin','hr');
    require_csrf();
    try{
        $action=$_POST['action']??'';$conn->begin_transaction();
        if($action==='schedule'){
            $employeeId=(int)($_POST['employee_id']??0);$weekday=(int)($_POST['weekday']??0);$workday=isset($_POST['is_workday'])?1:0;
            $in=trim((string)($_POST['expected_in']??''));$out=trim((string)($_POST['expected_out']??''));$grace=(int)($_POST['grace_minutes']??0);
            if($employeeId<=0||$weekday<1||$weekday>7||$grace<0||$grace>120)throw new InvalidArgumentException('Invalid employee, weekday or grace period.');
            if($workday&&(!preg_match('/^([01][0-9]|2[0-3]):[0-5][0-9]$/',$in)||!preg_match('/^([01][0-9]|2[0-3]):[0-5][0-9]$/',$out)||clock_minutes($out)<=clock_minutes($in)))throw new InvalidArgumentException('Working days need same-day expected in and out times.');
            $in=$workday?$in:null;$out=$workday?$out:null;$actor=(int)$_SESSION['admin_id'];
            $stmt=$conn->prepare('INSERT INTO employee_work_schedules(employee_id,weekday,is_workday,expected_in,expected_out,grace_minutes,updated_by) VALUES(?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE is_workday=VALUES(is_workday),expected_in=VALUES(expected_in),expected_out=VALUES(expected_out),grace_minutes=VALUES(grace_minutes),updated_by=VALUES(updated_by)');
            $stmt->bind_param('iiissii',$employeeId,$weekday,$workday,$in,$out,$grace,$actor);
            if(!$stmt->execute())throw new RuntimeException('Could not save work schedule.');
            lcc_audit($conn,'schedule_updated','employee',$employeeId,'Weekday '.$weekday.'; workday '.$workday.'; '.$in.'-'.$out.'; grace '.$grace);
            $message='Work schedule saved. No pay amount has been calculated.';
        }elseif($action==='overtime'){
            $attendanceId=(int)($_POST['attendance_id']??0);$approved=(int)($_POST['approved_minutes']??-1);$reason=trim((string)($_POST['reason']??''));
            if($attendanceId<=0||$approved<0||$approved>1440||$reason===''||strlen($reason)>255)throw new InvalidArgumentException('Enter valid approved minutes and a reason.');
            $stmt=$conn->prepare('SELECT a.employee_id,a.attendance_date,a.time_out,a.status,s.expected_out,s.is_workday FROM attendance a LEFT JOIN employee_work_schedules s ON s.employee_id=a.employee_id AND s.weekday=WEEKDAY(a.attendance_date)+1 WHERE a.attendance_id=? FOR UPDATE');
            $stmt->bind_param('i',$attendanceId);$stmt->execute();$row=$stmt->get_result()->fetch_assoc();
            if(!$row||!$row['is_workday']||in_array($row['status'],['Absent','On Leave'],true)||clock_minutes($row['time_out'])===null||clock_minutes($row['expected_out'])===null)throw new DomainException('This record has no complete working-day overtime evidence.');
            $recorded=max(0,clock_minutes($row['time_out'])-clock_minutes($row['expected_out']));
            if($approved>$recorded)throw new DomainException('Approved minutes cannot exceed recorded overtime.');
            $actor=(int)$_SESSION['admin_id'];
            $stmt=$conn->prepare('INSERT INTO attendance_overtime_approvals(attendance_id,approved_minutes,reason,approved_by) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE approved_minutes=VALUES(approved_minutes),reason=VALUES(reason),approved_by=VALUES(approved_by)');
            $stmt->bind_param('iisi',$attendanceId,$approved,$reason,$actor);
            if(!$stmt->execute())throw new RuntimeException('Could not save overtime approval.');
            lcc_audit($conn,'overtime_reviewed','attendance',$attendanceId,'Approved '.$approved.' of '.$recorded.' minutes; '.$reason);
            $message='Overtime minutes approved. Earnings still require an authorized income adjustment and configured rate.';
        }else throw new InvalidArgumentException('Unknown action.');
        $conn->commit();
    }catch(Throwable $e){$conn->rollback();$error=$e->getMessage();}
}
$employees=$conn->query("SELECT employee_id,employee_no,first_name,last_name FROM employees WHERE employment_status<>'Archived' ORDER BY last_name,first_name")->fetch_all(MYSQLI_ASSOC);
$periods=$conn->query('SELECT period_id,label,period_start,period_end,pay_date FROM payroll_periods ORDER BY period_start DESC')->fetch_all(MYSQLI_ASSOC);
$employeeId=(int)($_GET['employee_id']??$_POST['employee_id']??0);$periodId=(int)($_GET['period_id']??$_POST['period_id']??0);
$schedule=[];$rows=[];$totals=['late'=>0,'undertime'=>0,'overtime'=>0,'approved'=>0];
if($employeeId>0){$stmt=$conn->prepare('SELECT * FROM employee_work_schedules WHERE employee_id=? ORDER BY weekday');$stmt->bind_param('i',$employeeId);$stmt->execute();foreach($stmt->get_result()->fetch_all(MYSQLI_ASSOC) as $s)$schedule[(int)$s['weekday']]=$s;}
if($employeeId>0&&$periodId>0){
    $stmt=$conn->prepare('SELECT period_start,period_end,pay_date FROM payroll_periods WHERE period_id=?');$stmt->bind_param('i',$periodId);$stmt->execute();$period=$stmt->get_result()->fetch_assoc();
    if($period){$stmt=$conn->prepare('SELECT a.*,s.is_workday,s.expected_in,s.expected_out,s.grace_minutes,o.approved_minutes FROM attendance a LEFT JOIN employee_work_schedules s ON s.employee_id=a.employee_id AND s.weekday=WEEKDAY(a.attendance_date)+1 LEFT JOIN attendance_overtime_approvals o ON o.attendance_id=a.attendance_id WHERE a.employee_id=? AND a.attendance_date BETWEEN ? AND ? ORDER BY a.attendance_date');$stmt->bind_param('iss',$employeeId,$period['period_start'],$period['period_end']);$stmt->execute();$rows=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);
        foreach($rows as &$row){$row['late']=$row['undertime']=$row['overtime']=null;
            if($row['is_workday']&& !in_array($row['status'],['Absent','On Leave'],true)){
                $in=clock_minutes($row['time_in']);$out=clock_minutes($row['time_out']);$expectedIn=clock_minutes($row['expected_in']);$expectedOut=clock_minutes($row['expected_out']);
                if($in!==null&&$expectedIn!==null)$row['late']=max(0,$in-$expectedIn-(int)$row['grace_minutes']);
                if($out!==null&&$expectedOut!==null){$row['undertime']=max(0,$expectedOut-$out);$row['overtime']=max(0,$out-$expectedOut);}
            }
            foreach(['late','undertime','overtime'] as $key)if($row[$key]!==null)$totals[$key]+=$row[$key];
            $totals['approved']+=(int)($row['approved_minutes']??0);
        }unset($row);
    }
}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="icon" href="../assets/favicon.png"><title>LCC Payroll System</title><link rel="stylesheet" href="../assets/css/app.css?v=20261012-nav1"><link rel="stylesheet" href="../assets/css/apple-system.css?v=20261012-ux1"><script src="../assets/js/app.js?v=20261012-nav1" defer></script></head><body class="lcc-ux"><div class="app"><?php sidebar('attendance_payroll'); ?><main class="main"><?php topbar('Attendance Review'); ?><div class="content"><div class="page-heading"><div><div class="eyebrow">WORKFORCE</div><h1>Payroll Attendance Review</h1><p>Minutes use each employee's configured workday. Missing logs do not become absences or deductions automatically.</p></div><a class="btn btn-secondary" href="attendance.php">Daily Attendance</a></div><div class="lcc-help-strip"><div><strong>Review recorded hours</strong>Choose an employee and pay period. This page shows minutes for review; it does not change pay automatically.</div><a href="getting_started.php">See all steps →</a></div><?php if($error): ?><div class="notice err"><?php echo e($error); ?></div><?php endif; ?><?php if($message): ?><div class="notice ok"><?php echo e($message); ?></div><?php endif; ?><section class="card"><div class="card-head"><div><h2>Select employee and period</h2></div></div><form method="get" class="toolbar"><div><label>Employee</label><select name="employee_id" required><option value="">Select employee</option><?php foreach($employees as $employee): ?><option value="<?php echo (int)$employee['employee_id']; ?>" <?php echo (int)$employee['employee_id']===$employeeId?'selected':''; ?>><?php echo e($employee['employee_no'].' · '.$employee['last_name'].', '.$employee['first_name']); ?></option><?php endforeach; ?></select></div><div><label>Period</label><select name="period_id" required><option value="">Select period</option><?php foreach($periods as $periodOption): ?><option value="<?php echo (int)$periodOption['period_id']; ?>" <?php echo (int)$periodOption['period_id']===$periodId?'selected':''; ?>><?php echo e($periodOption['label']); ?></option><?php endforeach; ?></select></div><button class="btn btn-primary">Review</button></form></section>
<?php if($employeeId>0&&$canEditAttendance): ?><section class="card form-card"><div class="card-head"><div><h2>Work Schedule</h2><p>Set each weekday independently. The calculation supports same-day shifts; overnight shifts need a separate approved policy.</p></div></div><form method="post"><?php echo csrf_field(); ?><input type="hidden" name="action" value="schedule"><input type="hidden" name="employee_id" value="<?php echo $employeeId; ?>"><div class="form-body"><div class="form-grid"><div class="field"><label>Weekday</label><select name="weekday"><?php foreach(['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'] as $i=>$day): ?><option value="<?php echo $i+1; ?>"><?php echo $day; ?><?php echo isset($schedule[$i+1])?' · '.($schedule[$i+1]['is_workday']?'workday':'off'):''; ?></option><?php endforeach; ?></select></div><div class="field"><label><input type="checkbox" name="is_workday" value="1" checked> Working day</label></div><div class="field"><label>Expected in</label><input type="time" name="expected_in"></div><div class="field"><label>Expected out</label><input type="time" name="expected_out"></div><div class="field"><label>Grace minutes</label><input type="number" name="grace_minutes" min="0" max="120" value="0"></div></div></div><div class="form-actions"><button class="btn btn-primary">Save Schedule Day</button></div></form></section><?php endif; ?>
<?php if($employeeId>0&&$periodId>0): ?><section class="card"><div class="card-head"><div><h2>Attendance Summary</h2><p>Pay date: <?php echo e($period['pay_date']??'Unknown'); ?> · Late <?php echo $totals['late']; ?> min · Undertime <?php echo $totals['undertime']; ?> min · Recorded overtime <?php echo $totals['overtime']; ?> min · Approved overtime <?php echo $totals['approved']; ?> min. No pay adjustment is generated without a configured rate and authorized entry.</p></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Date</th><th>Status</th><th>In</th><th>Out</th><th>Schedule</th><th>Late</th><th>Undertime</th><th>Overtime</th><th>Approved</th><th>Review</th></tr></thead><tbody><?php if(!$rows): ?><tr><td colspan="10" class="empty">No recorded attendance in this period. Missing dates are not classified automatically.</td></tr><?php else: foreach($rows as $row): ?><tr><td><?php echo e($row['attendance_date']); ?></td><td><?php echo e($row['status']); ?></td><td><?php echo e($row['time_in']?:'—'); ?></td><td><?php echo e($row['time_out']?:'—'); ?></td><td><?php echo $row['is_workday']?e($row['expected_in'].' – '.$row['expected_out']):'Not configured / off'; ?></td><td><?php echo $row['late']===null?'—':(int)$row['late']; ?></td><td><?php echo $row['undertime']===null?'—':(int)$row['undertime']; ?></td><td><?php echo $row['overtime']===null?'—':(int)$row['overtime']; ?></td><td><?php echo $row['approved_minutes']===null?'—':(int)$row['approved_minutes']; ?></td><td><?php if($canEditAttendance&&$row['overtime']>0): ?><form method="post"><?php echo csrf_field(); ?><input type="hidden" name="action" value="overtime"><input type="hidden" name="employee_id" value="<?php echo $employeeId; ?>"><input type="hidden" name="period_id" value="<?php echo $periodId; ?>"><input type="hidden" name="attendance_id" value="<?php echo (int)$row['attendance_id']; ?>"><input type="number" name="approved_minutes" min="0" max="<?php echo (int)$row['overtime']; ?>" value="<?php echo (int)($row['approved_minutes']??0); ?>" aria-label="Approved overtime minutes" required><input name="reason" maxlength="255" placeholder="Approval reason" required><button class="btn btn-secondary btn-small">Save</button></form><?php endif; ?></td></tr><?php endforeach; endif; ?></tbody></table></div></section><?php endif; ?></div></main></div></body></html>
